  <script>
    const glow = document.body;
    let mouseActive = false;

    document.addEventListener('mousemove', (e) => {
      const x = e.clientX;
      const y = e.clientY;

      glow.style.setProperty('--mouse-x', x + 'px');
      glow.style.setProperty('--mouse-y', y + 'px');

      if (!mouseActive) {
        glow.classList.add('mouse-active');
        mouseActive = true;
      }
    });

    document.addEventListener('mouseleave', () => {
      glow.classList.remove('mouse-active');
      mouseActive = false;
    });

    const style = document.createElement('style');
    style.textContent = `
      body::after {
        left: calc(var(--mouse-x, 0px) - 200px);
        top: calc(var(--mouse-y, 0px) - 200px);
      }
    `;
    document.head.appendChild(style);

    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            entry.target.style.opacity = '1';
            entry.target.style.transform = 'translateY(0)';
          }
        });
      },
      { threshold: 0.1 }
    );

    document.querySelectorAll('section').forEach(section => {
      section.style.opacity = '0';
      section.style.transform = 'translateY(20px)';
      observer.observe(section);
    });

    document.getElementById("year").textContent = new Date().getFullYear();

    document.querySelectorAll('a[href^="#"]').forEach(anchor => {
      anchor.addEventListener('click', function(e) {
        e.preventDefault();
        const targetId = this.getAttribute('href');
        if (targetId === '#') return;
        const target = document.querySelector(targetId);
        if (target) {
          target.scrollIntoView({ behavior: 'smooth', block: 'start' });
        }
      });
    });

    function handleEmailClick(e) {
      e.preventDefault();
      const email = 'contact@notadi.in';
      const gmailUrl = `https://mail.google.com/mail/?view=cm&fs=1&to=${email}`;
      const mailtoUrl = `mailto:${email}`;

      // Try to open Gmail in a new tab
      const gmailWindow = window.open(gmailUrl, '_blank');

      // If the tab failed to open (e.g., popup blocker), fallback to system mail client
      if (!gmailWindow || gmailWindow.closed || typeof gmailWindow.closed === 'undefined') {
        window.location.href = mailtoUrl;
      }
    }

    window.addEventListener('scroll', () => {
      const scrollPercentage = (window.scrollY / (document.documentElement.scrollHeight - window.innerHeight)) * 100;
      const indicator = document.querySelector('.scroll-indicator') || (() => {
        const ind = document.createElement('div');
        ind.className = 'scroll-indicator';
        document.body.appendChild(ind);
        return ind;
      })();
      indicator.style.width = scrollPercentage + '%';
    }, { passive: true });
  </script>
</body>
</html>

